with scored as (select *, ntile(5) over (partition by promo_code, channel order by discount_pct desc, id) discount_pct_bucket, last_value(channel, true) over (partition by channel order by ends_on, id rows between unbounded preceding and current row) last_known_channel, first_value(channel, true) over w_running first_known_channel from promotions window w_running as (partition by promo_code order by ends_on, id rows between unbounded preceding and current row)) select id, channel, starts_on, ends_on, discount_pct_bucket, last_known_channel, first_known_channel from scored order by discount_pct_bucket desc
